class MySQLDatabase:
    def __init__(self):
        self.data = {}

    def insert(self, key: int, value: str) -> None:
        self.data[key] = value

    def update(self, key: int, value: str) -> None:
        if key in self.data:
            self.data[key] = value

    def delete(self, key: int) -> None:
        if key in self.data:
            del self.data[key]

    def fetch(self, key: int) -> str:
        return self.data.get(key, "Not Found")

class UserManager:
    def __init__(self, database: MySQLDatabase):
        self.database = database

    def add_user(self, id: int, name: str) -> None:
        if self.database.fetch(id) != "Not Found":
            print("User ID already exists. Use update_user_data to modify.")
        else:
            self.database.insert(id, name)
            print("User added successfully.")

    def update_user(self, id: int, name: str) -> None:
        if self.database.fetch(id) != "Not Found":
            self.database.update(id, name)
            print("User updated successfully.")
        else:
            print("User ID does not exist. Use add_user_data to add new user.")

    def delete_user(self, id: int) -> None:
        if self.database.fetch(id) != "Not Found":
            self.database.delete(id)
            print("User deleted successfully.")
        else:
            print("User ID not found.")
